const pageCopy={zh:{
 dtag:'DOWNLOAD & GET STARTED',dtitle:'从第一次打开，<br><span>到每天顺手。</span>',dintro:'安装 Orbi，让音乐、日程与复制过的文字，在 Mac 顶部随时就位。',status:'安装包准备中',package:'Orbi for Mac',packageText:'面向 macOS 的刘海工作台。正式安装包与版本信息将在这里提供。',meta:['平台 · macOS','签名 · 暂无 Developer ID 证书','兼容版本 · 发布时确认'],unavailable:'下载即将开放',jump:'先看看安装指南 ↓',nav:['安装与打开','首次使用','权限说明','常见问题'],install:'只需几步，<br><span>让 Orbi 就位。</span>',installIntro:'正式下载开放后，请从本站获取安装包。以下是安装与首次打开的操作指南。',steps:[['下载并放入应用程序','下载后，如果得到 ZIP 文件，先解压；如果得到 DMG 文件，先打开磁盘映像。将 Orbi.app 拖入“应用程序”文件夹，再从那里打开。'],['第一次打开，留意系统提示','当前版本暂未使用 Apple Developer ID 证书签名。macOS 可能会提示无法验证开发者或无法检查恶意软件；这不代表已经通过安全检查。'],['根据需要，设置功能权限','进入 Orbi 后，按系统提示查看日历、音乐控制或音频访问请求。每项用途见下方说明；允许应用打开与允许读取数据是两件不同的事。']],gateTitle:'遇到“无法验证开发者”？',gateIntro:'只有确认安装包来自可信来源且未被篡改，并接受未签名软件的风险后，才继续。',gateSteps:['先尝试打开一次 Orbi，关闭拦截提示。','进入“系统设置” → “隐私与安全性”，找到 Orbi 对应的拦截说明。','如果出现“仍要打开”，点按后再次确认“打开”，并按系统要求验证身份。'],gateNote:'若提示 App 已损坏、包含恶意软件或将损坏电脑，请停止安装，重新核实安装包。不要关闭系统整体安全保护。',apple:'查看 Apple 官方打开指南 ↗',first:'第一次使用，<br><span>从顶部开始。</span>',firstIntro:'Orbi 是一个菜单栏应用。打开后，把注意力移到屏幕顶部，而不是等待一个主窗口。',firstCards:[['01','移入，展开工作台','把鼠标移到屏幕顶部中央的刘海区域。音乐、日历和剪贴板会展开；移开后，工作台稍作停留再收起。'],['02','试试三个日常功能','播放 Apple Music、查看今天的日程，或复制一段普通文字。在工作台中控制音乐、查看安排、点选历史文字重新复制。'],['03','调整成自己的习惯','通过菜单栏的“打开设置”或工作台上的齿轮进入设置。选择显示的模块、开机启动，以及中文、英文或跟随系统。']],permissions:'每一项权限，<br><span>都说清楚。</span>',permissionIntro:'启动时可能出现权限请求。授权由 macOS 管理，你可以根据用途决定。系统版本不同，显示的名称也可能不同。',perms:[['日历','读取日程','用于显示今天正在进行或接下来的事件、时间和所属日历。当前应用请求日历完整访问权限；相关功能代码用于读取并展示事件。','不允许时，无法读取你的日历事件。'],['自动化 · 音乐','歌曲信息与控制','用于向 macOS 的“音乐”应用读取当前歌曲信息，并发送播放、暂停、上一首和下一首指令。请在系统请求控制“音乐”时按需允许。','不允许时，Apple Music 的歌曲信息和播放控制可能不可用。'],['系统音频','播放状态与律动','用于检测发声应用的音频活动，并驱动刘海旁的音量律动。如果 macOS 弹出音频访问请求，请核对应用名称和说明后决定。','不允许时，音频检测和律动可能不可用。'],['剪贴板','最近的文字记录','应用运行时读取新复制的文字，最多保留 15 条历史。点选可重新复制，也可以清空历史。它并不是一个名为“剪贴板”的常规系统授权开关。','模块显示开关只控制界面。当前版本隐藏模块不会停止剪贴板监测；需要停止时请退出 Orbi。']],manage:'管理已授予的权限',manageText:'日历与自动化等访问可在“系统设置 → 隐私与安全性”中查看和调整。修改后若功能未恢复，退出并重新打开 Orbi。开机启动在 Orbi 设置中控制；它与日历或音频访问无关。',faqTitle:'还有这些，<br><span>你可能想知道。</span>',faqs:[['为什么没有直接提供下载？','当前页面仍是官网预览。正式安装包、版本号和适配信息尚未上传，下载按钮因此暂不可用。'],['“仍要打开”没有出现怎么办？','先确认你已经尝试打开过 Orbi，再查看“隐私与安全性”。受组织管理的 Mac 可能限制此操作，请联系设备管理员。具体系统行为以 Apple 官方指南为准。'],['打开后没有看到窗口，是正常的吗？','是的。Orbi 的主要界面位于屏幕顶部，同时提供菜单栏入口。将鼠标移到顶部中央即可尝试展开。'],['所有音乐应用都能切歌吗？','当前代码中，歌曲信息与上一首、下一首、播放控制针对 Apple Music。其他发声应用主要展示应用名称、播放状态与音频律动。'],['关闭某个模块，就等于撤销权限吗？','不等于。模块开关控制是否在工作台显示。系统数据访问需要在 macOS 设置中管理，剪贴板监测则会在应用运行时持续进行。'],['如何清空剪贴板，或退出 Orbi？','在剪贴板模块使用清空历史按钮。需要结束应用时，从 Orbi 菜单栏菜单选择退出；仅移开鼠标会收起工作台，并不会退出。']],
 atag:'ABOUT ORBI',atitle:'让小小的日常，<br><span>变得更顺手。</span>',aintro:'我们正在为 Mac 打造一个轻巧的顶部工作台。<br>少一次切换，多一点专注。',originTag:'WHY ORBI',originTitle:'从屏幕顶部，<br>重新想一想日常。',originBody:['一首歌想跳过，一场日程快开始，一段文字刚刚复制。这些事很小，却常常让我们离开手头的窗口。','Orbi 围绕这些日常动作，把音乐、日历和剪贴板放在同一个地方。需要时移入，不用时收起，让工具顺着你的节奏出现。'],statement:'我们想做的，<br>不是占据更多注意力。<br><span>而是让你更少分心。</span>',valuesTitle:'每一个细节，<br><span>都有一个简单的出发点。</span>',values:[['01 / 轻巧','出现得恰到好处','把常用信息放在屏幕顶部，不为每个小动作再开一个窗口。收起与展开，都服务于当下的任务。'],['02 / 清晰','一眼知道，下一步','音乐、日历、剪贴板，各有自己的位置。让正在播放的内容、接下来的安排和刚复制的文字更容易找到。'],['03 / 自主','让习惯决定工具','按需显示模块，选择语言与开机启动。工具应该容纳不同的工作方式，而不是要求你适应它。']],todayTag:'ORBI, TODAY',todayTitle:'从三个功能，<br><span>认真开始。</span>',todayBody:'目前，Orbi 聚焦 Apple Music 控制、今日日程展示和文字剪贴板。我们希望先把这些每天会用到的小事，做得清楚、自然。',todayItems:['音乐 · 当前曲目与播放控制','日历 · 今日与即将开始的安排','剪贴板 · 最近 15 条文字记录'],transTitle:'也把当前状态，<br><span>坦诚告诉你。</span>',transBody:'Orbi 仍在完善中。目前没有 Apple Developer ID 签名证书，本站暂未提供正式安装包。下载开放时，我们会明确列出版本、兼容系统与首次打开说明。',transNote:'Orbi 是独立应用，并非 Apple 官方产品。Apple、Mac、macOS 和 Apple Music 名称用于说明适用平台及集成功能。',end:'从顶部，开始认识 Orbi。',view:'探索产品',guide:'阅读使用指南'},en:{
 dtag:'DOWNLOAD & GET STARTED',dtitle:'From your first launch.<br><span>To your everyday flow.</span>',dintro:'Bring music, your schedule, and copied text together at the top of your Mac.',status:'Installer in preparation',package:'Orbi for Mac',packageText:'A notch workspace for macOS. The release installer and version details will be available here.',meta:['Platform · macOS','Signing · No Developer ID certificate yet','Compatibility · To be confirmed'],unavailable:'Download coming soon',jump:'Explore the setup guide ↓',nav:['Install & open','First steps','Permissions','FAQ'],install:'A few simple steps.<br><span>A new place to begin.</span>',installIntro:'Once downloads open, get the installer from this site. Here is how to install and open Orbi for the first time.',steps:[['Download and move to Applications','If the download is a ZIP, extract it first. If it is a DMG, open the disk image. Move Orbi.app into Applications, then open it from there.'],['Review the first-launch message','The current version is not signed with an Apple Developer ID certificate. macOS may be unable to verify the developer or check for malicious software. This does not mean the app has passed a safety check.'],['Review feature permissions','Read any calendar, music-control, or audio-access requests. Each purpose is explained below. Allowing an app to open is separate from allowing it to access your data.']],gateTitle:'Can’t verify the developer?',gateIntro:'Continue only if you trust the source, know the installer has not been altered, and accept the risks of unsigned software.',gateSteps:['Try opening Orbi once and dismiss the blocked-app message.','Open System Settings → Privacy & Security and find the notice about Orbi.','If Open Anyway is available, select it, confirm Open, and authenticate if requested.'],gateNote:'Stop if macOS reports damage or malicious software. Verify the installer instead of disabling system-wide protection.',apple:'Read Apple’s official guide ↗',first:'Your first steps.<br><span>Start at the top.</span>',firstIntro:'Orbi is a menu bar app. After opening it, look at the top of your screen instead of waiting for a main window.',firstCards:[['01','Move in. Open up.','Move your pointer to the notch area at the top center of the screen. Your workspace opens; move away and it closes after a short pause.'],['02','Try the everyday essentials','Play something in Apple Music, check today’s schedule, or copy ordinary text. Control playback, see events, and select a history entry to copy it again.'],['03','Make it feel like yours','Use Open Settings in the menu bar, or the gear in the workspace. Choose visible modules, launch at login, and English, Chinese, or system language.']],permissions:'Every permission.<br><span>A clear purpose.</span>',permissionIntro:'Permission requests may appear at startup. macOS manages these requests; review their purpose before deciding. Names may vary by system version.',perms:[['Calendar','Read your schedule','Shows today’s current or upcoming event, time, and calendar. The current app requests full calendar access; its calendar feature reads and displays events.','Without access, Orbi cannot read your calendar events.'],['Automation · Music','Track details and controls','Reads the current track from the macOS Music app and sends play, pause, previous, and next commands. Review requests to control Music.','Without access, Apple Music details and playback controls may be unavailable.'],['System audio','Playback activity and waveform','Detects audio activity from playing apps to drive the notch waveform. If macOS asks for audio access, check the app name and request before deciding.','Without access, audio detection and the waveform may be unavailable.'],['Clipboard','Recent copied text','While running, Orbi reads newly copied text and keeps up to 15 entries. Select an entry to copy it again, or clear the history. There is no standard system permission switch named Clipboard.','Module switches affect visibility. Hiding the clipboard module does not stop monitoring in the current version; quit Orbi to stop it.']],manage:'Manage permissions later',manageText:'Review calendar, automation, and related access in System Settings → Privacy & Security. Restart Orbi if a change is not reflected. Launch at login is controlled in Orbi settings and is separate from data access.',faqTitle:'A few more things.<br><span>Good to know.</span>',faqs:[['Why is the download unavailable?','This is still a website preview. The installer, release version, and compatibility details have not been uploaded, so downloading is not enabled yet.'],['What if Open Anyway is missing?','Try opening Orbi first, then check Privacy & Security. Managed Macs may restrict this; ask your device administrator. Refer to Apple’s guide for your system.'],['Is it normal not to see a main window?','Yes. Orbi lives at the top of the screen and provides a menu bar entry. Move your pointer to the top center to reveal the workspace.'],['Can every music app skip tracks?','Current track details and playback controls are implemented for Apple Music. Other audio apps primarily show their name, playback activity, and waveform.'],['Does hiding a module revoke its permissions?','No. Module switches control visibility. Manage system data access in macOS settings. Clipboard monitoring continues while the app is running.'],['How do I clear clipboard history or quit?','Use the clear-history button in the clipboard module. To exit, choose Quit from Orbi’s menu bar menu. Moving your pointer away only closes the workspace.']],
 atag:'ABOUT ORBI',atitle:'Little everyday moments.<br><span>A little more effortless.</span>',aintro:'We’re building a lightweight workspace at the top of your Mac.<br>Fewer switches. More focus.',originTag:'WHY ORBI',originTitle:'Everyday essentials.<br>A different point of view.',originBody:['A song to skip. A meeting about to start. A line of text you just copied. Small things that can pull you away from the window in front of you.','Orbi brings those moments together: music, calendar, and clipboard in one place. Move in when you need it. Move away when you don’t. A tool that follows your rhythm.'],statement:'Our aim is not to take<br>more of your attention.<br><span>It’s to ask for less.</span>',valuesTitle:'Considered details.<br><span>Simple intentions.</span>',values:[['01 / LIGHTWEIGHT','There at the right moment','Keep useful information at the top of your screen, without opening another window for every little task.'],['02 / CLEAR','Know what comes next','Music, calendar, and clipboard each have a place. Find what’s playing, what’s next, and what you just copied.'],['03 / PERSONAL','Your habits come first','Choose visible modules, language, and launch at login. A tool should make room for the way you work.']],todayTag:'ORBI, TODAY',todayTitle:'Three essentials.<br><span>A thoughtful beginning.</span>',todayBody:'Today, Orbi focuses on Apple Music controls, today’s events, and text clipboard history. We want to make these everyday moments feel clear and natural.',todayItems:['Music · Current track and playback controls','Calendar · Today’s current or next event','Clipboard · Your 15 most recent text entries'],transTitle:'Where we are.<br><span>Clearly stated.</span>',transBody:'Orbi is still being refined. It does not yet have an Apple Developer ID signing certificate, and a release installer is not available on this site. When downloads open, we’ll include version, compatibility, and first-launch information.',transNote:'Orbi is an independent app, not an official Apple product. Apple, Mac, macOS, and Apple Music names identify supported platforms and integrations.',end:'Meet Orbi. Right at the top.',view:'Explore the product',guide:'Read the guide'}};
Object.assign(pageCopy.zh,{status:'Orbi 1.0 · 现已提供下载',packageText:'下载 Orbi 1.0 的 DMG 安装包。打开后，将 Orbi 拖入“应用程序”文件夹。',unavailable:'下载 Orbi 1.0',installIntro:'点击上方下载按钮，获取 Orbi-1.0.dmg。随后按图示安装，再参考下方首次打开说明。',transBody:'Orbi 1.0 现已提供 DMG 下载。目前没有 Apple Developer ID 签名证书，首次打开可能需要在系统设置中确认。适配系统信息仍待确认，请在安装前阅读使用指南。',imageAlt:'Orbi 安装图解：打开下载的 DMG，将 Orbi 拖入 Applications，再从应用程序文件夹打开。',imageCaption:'安装三步：打开 DMG → 拖入“应用程序” → 打开 Orbi。图片中的 Orbi.dmg 对应本次下载的 Orbi-1.0.dmg。',imageFull:'查看完整安装图 ↗'});
Object.assign(pageCopy.en,{status:'Orbi 1.0 · Available to download',packageText:'Download the Orbi 1.0 DMG installer. Open it, then drag Orbi into Applications.',unavailable:'Download Orbi 1.0',installIntro:'Use the download button above to get Orbi-1.0.dmg. Follow the illustrated installation steps, then review the first-launch guidance below.',transBody:'Orbi 1.0 is now available as a DMG download. It does not yet have an Apple Developer ID signing certificate, so the first launch may require confirmation in System Settings. System compatibility is still to be confirmed; read the guide before installing.',imageAlt:'Orbi installation: open the downloaded DMG, drag Orbi into Applications, then open Orbi from Applications.',imageCaption:'Open the DMG → Drag to Applications → Open Orbi. The image’s Orbi.dmg refers to the Orbi-1.0.dmg download provided here.',imageFull:'View full installation image ↗'});
pageCopy.zh.steps[0]=['下载并放入应用程序','点击“下载 Orbi 1.0”，双击下载完成的 Orbi-1.0.dmg。把窗口里的 Orbi 拖入 Applications（应用程序），等待复制完成，再从“应用程序”中打开 Orbi。'];
pageCopy.en.steps[0]=['Download and move to Applications','Click Download Orbi 1.0, then double-click Orbi-1.0.dmg. Drag Orbi into Applications in the installer window, wait for the copy to finish, and open Orbi from Applications.'];
pageCopy.zh.faqs[0]=['下载后应该打开哪个文件？','打开 Orbi-1.0.dmg，将 Orbi 拖入“应用程序”。复制完成后，可推出磁盘映像；以后从“应用程序”启动 Orbi。'];
pageCopy.en.faqs[0]=['Which file should I open after downloading?','Open Orbi-1.0.dmg and drag Orbi into Applications. Once copying finishes, eject the disk image and launch Orbi from Applications.'];
pageCopy.zh.meta.push('DMG · 3.4 MB');pageCopy.en.meta.push('DMG · 3.4 MB');
function downloadPage(){const t=pageCopy[lang];return `<section class="hero info-hero"><div class="eyebrow">${t.dtag}</div><h1>${t.dtitle}</h1><p>${t.dintro}</p><div class="release-card"><img src="/assets/orbi-icon.png" width="84" height="84" alt="Orbi"><div class="release-copy"><span class="release-status">${t.status}</span><h2>${t.package}</h2><p>${t.packageText}</p></div><a class="pill download-button" href="/downloads/Orbi-1.0.dmg" download="Orbi-1.0.dmg">${t.unavailable} ↓</a><ul class="release-meta">${t.meta.map(s=>`<li>${s}</li>`).join('')}</ul></div><a class="textlink guide-jump" href="#install">${t.jump}</a></section><nav class="guide-nav" aria-label="${lang==='zh'?'使用指南章节':'Guide sections'}">${['install','first-use','permissions','faq'].map((id,i)=>`<a href="#${id}">${t.nav[i]}</a>`).join('')}</nav><section class="section" id="install"><div class="section-heading"><span class="eyebrow">01 / SETUP</span><h2>${t.install}</h2><p>${t.installIntro}</p></div><figure class="install-figure"><a href="/assets/orbi-install-guide.png" target="_blank" rel="noopener noreferrer"><img src="/assets/orbi-install-guide.png" width="1672" height="940" alt="${t.imageAlt}" loading="lazy"></a><figcaption>${t.imageCaption} <a href="/assets/orbi-install-guide.png" target="_blank" rel="noopener noreferrer">${t.imageFull}</a></figcaption></figure><div class="steps">${t.steps.map((s,i)=>`<article class="step reveal"><div class="step-number">0${i+1}</div><div><h3>${s[0]}</h3><p>${s[1]}</p></div></article>`).join('')}</div><aside class="gatekeeper"><div class="gate-heading"><span class="gate-symbol" aria-hidden="true">!</span><h3>${t.gateTitle}</h3></div><p>${t.gateIntro}</p><ol>${t.gateSteps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="gate-note">${t.gateNote}</p><a class="textlink" href="https://support.apple.com/${lang==='zh'?'zh-cn':'en-us'}/102445" target="_blank" rel="noopener noreferrer">${t.apple}</a></aside></section><section class="soft-section" id="first-use"><div class="section"><div class="section-heading"><span class="eyebrow">02 / FIRST STEPS</span><h2>${t.first}</h2><p>${t.firstIntro}</p></div><div class="onboarding-cards">${t.firstCards.map(s=>`<article class="onboarding-card reveal"><span class="num">${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p></article>`).join('')}</div></div></section><section class="section" id="permissions"><div class="section-heading"><span class="eyebrow">03 / PERMISSIONS</span><h2>${t.permissions}</h2><p>${t.permissionIntro}</p></div><div class="permission-grid">${t.perms.map((s,i)=>`<article class="permission-card reveal"><span class="permission-tag">0${i+1} / ${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p><div class="permission-detail">${s[3]}</div></article>`).join('')}</div><div class="manage-note"><h3>${t.manage}</h3><p>${t.manageText}</p></div></section><section class="soft-section" id="faq"><div class="section faq-section"><span class="eyebrow">04 / FAQ</span><h2>${t.faqTitle}</h2>${t.faqs.map(s=>`<details class="permission"><summary>${s[0]}</summary><p>${s[1]}</p></details>`).join('')}</div></section>`}
function aboutPage(){const t=pageCopy[lang];return `<section class="hero about-hero"><img src="/assets/orbi-icon.png" width="76" height="76" class="app-icon" alt="Orbi"><div class="eyebrow">${t.atag}</div><h1>${t.atitle}</h1><p>${t.aintro}</p></section><section class="section origin-section"><div><span class="eyebrow">${t.originTag}</span><h2>${t.originTitle}</h2></div><div class="origin-copy">${t.originBody.map(s=>`<p>${s}</p>`).join('')}</div></section><section class="dark manifesto"><div class="section center reveal"><div class="eyebrow">OUR PHILOSOPHY</div><h2>${t.statement}</h2></div></section><section class="section"><div class="section-heading"><h2>${t.valuesTitle}</h2></div><div class="values-grid">${t.values.map(s=>`<article class="value-card reveal"><span class="eyebrow">${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p></article>`).join('')}</div></section><section class="soft-section"><div class="section today-section"><div><span class="eyebrow">${t.todayTag}</span><h2>${t.todayTitle}</h2><p>${t.todayBody}</p></div><ul class="today-list">${t.todayItems.map((s,i)=>`<li><span>0${i+1}</span>${s}</li>`).join('')}</ul></div></section><section class="section transparency-section"><h2>${t.transTitle}</h2><div><p>${t.transBody}</p><p class="small">${t.transNote}</p><a href="/download/#install" class="textlink">${t.guide} ↗</a></div></section><section class="section center about-end"><h2>${t.end}</h2><div class="actions"><a class="pill" href="/">${t.view}</a><a class="textlink" href="/download/">${t.guide} ↗</a></div></section>`}
